<?php

declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Content\{ContentVersionRepository,QuestionRepository};
final class ReviewPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);$v=(new ContentVersionRepository)->getPublished();$questions=(new QuestionRepository)->forVersion((int)$v['id']);echo'<div class="wrap"><h1>Content Review</h1><p><strong>Launch gate:</strong> content is not technically approved until named Acorn reviewers complete these fields.</p><table class="widefat"><thead><tr><th>Question</th><th>Reviewer</th><th>Last reviewed</th><th>Next review</th><th>Status</th></tr></thead><tbody>';foreach($questions as$q){$due=empty($q['reviewed_by'])||$q['last_reviewed']==='1970-01-01'||$q['next_review']<=gmdate('Y-m-d');echo'<tr><td>'.esc_html($q['question_key']).'</td><td>'.esc_html($q['reviewed_by']?:'Outstanding').'</td><td>'.esc_html($q['last_reviewed']).'</td><td>'.esc_html($q['next_review']).'</td><td>'.($due?'Review required':'Current').'</td></tr>';}echo'</tbody></table></div>';}}
